let pulse = {};
try {
  const pulseRaw = (($('Leer repo pulse').first().json.stdout) || '{}').trim();
  pulse = JSON.parse(pulseRaw) || {};
} catch (e) {
  pulse = {};
}
const raw = ((items[0].json.stdout) || '').trim();
let payload;
try { payload = JSON.parse(raw); } catch (e) { payload = { ok: false, message: 'Briefing: no se pudo parsear la respuesta del VPS.' }; }
const data = payload.data || {};
const roles = Array.isArray(data.roles) ? data.roles : [];
const result = payload.result || {};
const date = data.date || new Date().toISOString().slice(0, 10);
const createdTasks = Array.isArray(result.createdTasks) ? result.createdTasks.length : (typeof result.createdTasks === 'number' ? result.createdTasks : 0);
const skippedTasks = Array.isArray(result.skippedTasks) ? result.skippedTasks.length : (typeof result.skippedTasks === 'number' ? result.skippedTasks : 0);
const lines = [
  `ONIA Center | Plan diario ${date}`,
  payload.message || 'Briefing generado.',
  `Tareas nuevas: ${createdTasks}. Omitidas por duplicado: ${skippedTasks}.`,
  '',
];
if (pulse && typeof pulse.totalCommits === 'number') {
  lines.push(`Repo (ultimas ${pulse.lookbackHours || '?'}h): ${pulse.totalCommits} commits.`);
  const topLanes = (pulse.byLane || []).slice(0, 5).map((l) => `${l.lane} (${l.commits})`).join(', ');
  if (topLanes) lines.push(`Carriles activos: ${topLanes}`);
  const stale = (pulse.staleLanes || []).slice(0, 5).map((l) => `${l.lane}${l.daysSinceLastCommit != null ? ' (' + l.daysSinceLastCommit + 'd)' : ' (sin historial)'}`);
  if (stale.length) lines.push(`Sin actividad: ${stale.join(', ')}`);
  lines.push('');
}
for (const role of roles) {
  const tasks = Array.isArray(role.topTasks) ? role.topTasks.slice(0, 5) : [];
  lines.push(`${String(role.role || '').toUpperCase()}: ${role.summary || 'Sin resumen.'}`);
  for (const task of tasks) {
    lines.push(`- ${task.timeBlock || 'sin bloque'} | ${task.title || 'Tarea sin titulo'}`);
  }
  lines.push('');
}
lines.push('Regla: solo cuenta si queda registrado con evidencia. n8n agenda y avisa; Sergio aprueba pagos, descuentos, gastos y uso premium.');
const text = lines.join('\n').slice(0, 3900);
return [{
  json: {
    ok: Boolean(payload.ok),
    mode: payload.mode,
    date,
    text,
    calendarBlocks: Array.isArray(data.calendarBlocks) ? data.calendarBlocks : [],
    createdTasks,
    skippedTasks,
    repoPulse: pulse
  }
}];

const item = items[0].json;
return [{
  json: {
    ok: item.ok,
    mode: item.mode,
    date: item.date,
    calendarReady: false,
    calendarBlocks: item.calendarBlocks,
    note: 'Google Calendar queda preparado. Activar escritura solo despues de OAuth y prueba manual.'
  }
}];
